# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require "rails_helper"

RSpec.describe Timekeeping::SnapshotEndpoint do
  it "logs a refused delivery once by status and fixed reason without any token or response text" do
    token = "service-#{SecureRandom.hex(24)}"
    answer = TimekeepingRelay::Response.new(status: 401, body: { "reason" => "Bearer #{token}\nINFO forged line" })
    inner = Object.new
    inner.define_singleton_method(:deliver) { |_batch, idempotency_key:| answer }
    log = StringIO.new
    logger = Logger.new(log).tap { |capture| capture.level = Logger::DEBUG }

    returned = with_timekeeping_env(Timekeeping::Environment::SERVICE_TOKEN => token) do
      described_class.new(endpoint: inner, logger: logger)
                     .deliver({ "schema_version" => 1, "snapshots" => [] }, idempotency_key: SecureRandom.uuid)
    end

    expect([returned.status, returned.body]).to eq([answer.status, answer.body])
    # "No token is written to a payload or a log line."
    expect(log.string).not_to include(token)
    expect(log.string).not_to include("forged")
    expect(log.string.lines.size).to eq(1)
    expect(log.string).to include("401")
    expect(log.string).to include("unrecognized")
  end

  it "writes no log line for a 200 answer" do
    answer = TimekeepingRelay::Response.new(status: 200, body: { "applied" => 0, "ignored" => 0 })
    inner = Object.new
    inner.define_singleton_method(:deliver) { |_batch, idempotency_key:| answer }
    log = StringIO.new
    logger = Logger.new(log).tap { |capture| capture.level = Logger::DEBUG }

    described_class.new(endpoint: inner, logger: logger)
                   .deliver({ "schema_version" => 1, "snapshots" => [] }, idempotency_key: SecureRandom.uuid)

    expect(log.string).to eq("")
  end
end
